create table if not exists event_category_boosts
(
    id                bigint primary key,
    event_template_id bigint        not null references event_templates (id) on delete cascade,
    tag               varchar(160)  not null,
    multiplier        numeric(5, 2) not null check (multiplier >= 1),
    rationale         text          not null,
    source_title      varchar(255)  not null,
    source_url        text          not null
);

create index if not exists idx_event_category_boosts_template on event_category_boosts (event_template_id);
create index if not exists idx_event_category_boosts_tag on event_category_boosts (tag);

